#import <Foundation/Foundation.h>
#import <IOKit/hid/IOHIDEventSystemClient.h>
#import <IOKit/hid/IOHIDEvent.h>
#import <IOKit/hid/IOHIDEventData.h>
#import <mach/mach_time.h>
#import <unistd.h>

int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "usage: tap X Y [count]\n"); return 2; }
    long x = atol(argv[1]);
    long y = atol(argv[2]);

    IOHIDEventSystemClientRef client = IOHIDEventSystemClientCreate(kCFAllocatorDefault);
    CFArrayRef svcs = IOHIDEventSystemClientCopyServices(client);
    if (!svcs) { fprintf(stderr, "no services\n"); return 3; }
    IOHIDServiceClientRef digitizer = NULL;
    CFIndex n = CFArrayGetCount(svcs);
    for (CFIndex i = 0; i < n; i++) {
        IOHIDServiceClientRef s = (IOHIDServiceClientRef)CFArrayGetValueAtIndex(svcs, i);
        CFNumberRef page = (CFNumberRef)IOHIDServiceClientGetProperty(s, CFSTR("PrimaryUsagePage"));
        CFNumberRef usage = (CFNumberRef)IOHIDServiceClientGetProperty(s, CFSTR("PrimaryUsage"));
        int p = 0, u = 0;
        if (page) CFNumberGetValue(page, kCFNumberIntType, &p);
        if (usage) CFNumberGetValue(usage, kCFNumberIntType, &u);
        fprintf(stderr, "svc %ld: page=0x%x usage=0x%x\n", (long)i, p, u);
        if (p == 0x0D && u == 0x04) { digitizer = s; }
    }
    if (!digitizer) { fprintf(stderr, "no digitizer touchscreen service\n"); return 4; }

    for (int phase = 0; phase < 2; phase++) {
        bool down = (phase == 0);
        uint64_t mt = mach_absolute_time();
        AbsoluteTime t = *(AbsoluteTime *)&mt;
        IOHIDEventRef e = IOHIDEventCreateDigitizerEvent(
            kCFAllocatorDefault, t,
            kIOHIDDigitizerTransducerTypeHand,
            0, 0,
            (IOHIDDigitizerEventMask)(kIOHIDDigitizerEventRange | kIOHIDDigitizerEventTouch | kIOHIDDigitizerEventPosition),
            (uint32_t)x, (uint32_t)y,
            0, 0, down, down, 0);
        IOHIDServiceClientDispatchEvent(digitizer, e);
        CFRelease(e);
        usleep(80000);
    }
    fprintf(stderr, "tapped %ld %ld\n", x, y);
    return 0;
}

